css:
/* ==========================================================================
   SHIBU PANDIT – DESIGN SYSTEM (rebuild 2026)
   Accent: --ac · Background #0E0F0F · Text #FEFCE1 / #BBBAA6 · Font: Inter Tight
   ========================================================================== */
:root{--ac:#FF7A45;--bg:#0E0F0F;--text:#FEFCE1;--text-2:#BBBAA6;--muted:#8A8A84}
html{scroll-behavior:smooth}
body{margin:0;--ac:#FF7A45;position:relative;isolation:isolate;background:#0E0F0F;color:#FEFCE1;font-family:'Inter Tight',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;overflow-x:clip;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
a{color:#FEFCE1;text-decoration:none}
img{max-width:100%}
:where(h1,h2,h3,h4,p,figure,blockquote){margin:0}
:where(main){display:block}
.screen-reader-text,.sx-sr{position:absolute !important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.sx-btn{display:inline-flex;align-items:center;gap:10px;min-height:48px;padding:0 24px;border-radius:999px;font-weight:400;font-size:15px;transition:all .3s ease-in-out}
.sx-btn-primary{background:var(--ac);color:#0E0F0F;box-shadow:0 0 0 0 transparent}
.sx-btn-primary:hover{background:#FEFCE1;color:#0E0F0F;transform:translateY(-2px);box-shadow:0 10px 30px color-mix(in srgb, var(--ac) 40%, transparent)}
.sx-btn svg{transition:transform .3s ease-in-out}
.sx-btn-primary:hover svg{transform:translateX(4px)}
.sx-btn-primary:active{transform:translateY(0) scale(.98)}
.sx-btn-ghost{border:1px solid rgba(254,252,225,0.28);color:#FEFCE1;background:transparent}
button.sx-btn{font-family:inherit;cursor:pointer;-webkit-appearance:none;appearance:none}
.sx-btn-ghost:hover{border-color:var(--ac);color:var(--ac);background:color-mix(in srgb, var(--ac) 8%, transparent)}
.sx-tab{all:unset;display:block;width:100%;cursor:pointer;border-top:1px solid rgba(255,255,255,0.08);padding:26px 0 24px}
.sx-tab:hover .sx-tab-title{color:#FEFCE1 !important}
.sx-step{all:unset;cursor:pointer;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;align-self:start;text-align:left}
.sx-faq{all:unset;cursor:pointer;display:flex;width:100%;align-items:center;justify-content:space-between;gap:20px;padding:24px 0;font-size:18px;font-weight:400}
.sx-faq:hover span:first-child{color:#ffffff}
.sx-marquee{display:flex;gap:20px;width:max-content;animation:sx-scroll 60s linear infinite}
.sx-marquee-wrap:hover .sx-marquee{animation-play-state:paused}
@keyframes sx-scroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sx-fade{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 10%,#000 90%,transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 10%,#000 90%,transparent 100%)}
@media (max-width:1608px){.sx-marquee-wrap{margin-left:24px !important;margin-right:24px !important}}
.sx-logo{color:#6f6f6a;transition:color .3s ease-in-out}
.sx-logo:hover{color:var(--ac)}
.sx-logo-img{filter:grayscale(1) brightness(.75);opacity:.8;transition:all .3s ease-in-out}
.sx-logo:hover .sx-logo-img{filter:grayscale(0) brightness(1);opacity:1}
@keyframes sx-fillA{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes sx-fillB{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes sx-inA{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@keyframes sx-inB{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.sx-split-svc:hover .sx-svc-fill{animation-play-state:paused !important}
@media (prefers-reduced-motion:reduce){.sx-svc-fill{animation:none !important}}
@media (min-width:901px){.sx-sec{padding-top:118px !important;padding-bottom:118px !important}.sx-sec-hero{padding-top:84px !important;padding-bottom:104px !important}}
.sx-cta{background:radial-gradient(55% 80% at 12% 0%,rgba(254,252,225,0.07),transparent 70%),radial-gradient(45% 70% at 90% 100%,color-mix(in srgb,var(--ac) 16%,transparent),transparent 70%),#121312}
.sx-cta-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none}
.sx-hdr{position:sticky;top:0;z-index:50;padding:18px 24px 0;box-sizing:border-box;transition:padding .45s cubic-bezier(.2,.8,.2,1)}
.sx-hdr-bar{max-width:1348px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:8px 0;border:1px solid transparent;border-radius:999px;background:transparent;transition:max-width .5s cubic-bezier(.2,.8,.2,1),padding .45s cubic-bezier(.2,.8,.2,1),background .45s ease,border-color .45s ease,box-shadow .45s ease}
.sx-hdr.is-scrolled{padding-top:12px}
.sx-hdr.is-scrolled .sx-hdr-bar{max-width:1040px;padding:8px 8px 8px 18px;background:rgba(18,19,18,0.78);border-color:rgba(255,255,255,0.1);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);box-shadow:0 14px 40px rgba(0,0,0,0.45)}
.sx-brand{display:flex;align-items:center;gap:12px;font-size:17px;font-weight:600;letter-spacing:-0.01em}
.sx-nav{position:relative;display:flex;gap:2px;padding:5px;border-radius:999px;border:1px solid rgba(255,255,255,0.08);background:rgba(255,255,255,0.025)}
.sx-nav-ind{position:absolute;top:5px;bottom:5px;border-radius:999px;background:rgba(254,252,225,0.09);pointer-events:none;transition:left .4s cubic-bezier(.2,.8,.2,1),width .4s cubic-bezier(.2,.8,.2,1),opacity .25s ease}
.sx-nav-a{position:relative;z-index:1;padding:9px 16px;border-radius:999px;font-size:14.5px;color:#BBBAA6;transition:color .3s ease}
.sx-nav-a:hover{color:#FEFCE1}
.sx-wa{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);color:#BBBAA6;transition:all .3s ease}
.sx-wa:hover{color:#25D366;border-color:#25D366;background:rgba(37,211,102,0.08)}
.sx-hire{min-height:42px !important;padding:0 16px 0 14px !important;font-size:14px !important;border-radius:999px !important;gap:9px !important}
.sx-pulse{position:relative;width:7px;height:7px;border-radius:50%;background:#0E0F0F}
.sx-pulse::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:1.5px solid #0E0F0F;opacity:0;animation:sx-pulse 2s ease-out infinite}
@keyframes sx-pulse{0%{transform:scale(.5);opacity:.7}100%{transform:scale(1.6);opacity:0}}
.sx-burger{all:unset;display:none;width:42px;height:42px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);align-items:center;justify-content:center;cursor:pointer;color:#FEFCE1}
.sx-soc{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:12px;border:1px solid rgba(255,255,255,0.12);color:#A9A895;transition:all .3s ease-in-out}
.sx-soc:hover{color:var(--ac);border-color:var(--ac);transform:translateY(-2px)}
.sx-flink{font-size:15px;color:#A9A895;transition:color .3s ease-in-out}
.sx-flink:hover{color:var(--ac)}
.sx-wordmark{margin-top:72px;text-align:center;font-size:clamp(64px,15.5vw,212px);line-height:.82;font-weight:600;letter-spacing:-0.06em;white-space:nowrap;background:linear-gradient(180deg,rgba(254,252,225,0.16),rgba(254,252,225,0.02) 85%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;padding-bottom:18px;user-select:none}
@media (min-width:901px){.sx-mmenu{display:none !important}}
@media (max-width:900px){.sx-nav{display:none !important}.sx-burger{display:inline-flex}.sx-hdr-bar .sx-hire,.sx-hdr-bar .sx-wa{display:none !important}.sx-hdr.is-scrolled .sx-hdr-bar{padding:6px 6px 6px 12px}}
@media (prefers-reduced-motion:reduce){.sx-pulse::after{animation:none}}
.sx-upw{display:inline-flex;align-items:center;gap:12px;margin-top:22px;padding:10px 14px 10px 16px;border-radius:999px;border:1px solid rgba(255,255,255,0.12);font-size:13px;color:#E4E2CB;transition:all .3s ease-in-out}
.sx-upw:hover{border-color:#14A800;background:rgba(20,168,0,0.08);transform:translateY(-2px)}
.sx-why{padding:30px;border-radius:20px;transition:border-color .35s ease,background .35s ease,transform .35s ease}
.sx-why:hover{border-color:color-mix(in srgb,var(--ac) 40%,transparent);background:linear-gradient(140deg,rgba(255,255,255,0.1),rgba(255,255,255,0.03) 45%,rgba(255,255,255,0.05));transform:translateY(-4px)}
.sx-why-ic{display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;border-radius:16px;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.05);transition:border-color .35s ease}
.sx-why:hover .sx-why-ic{border-color:color-mix(in srgb,var(--ac) 45%,transparent)}
.ic-bars{display:flex;align-items:flex-end;gap:4px;height:22px}
.ic-bars i{display:block;width:4px;border-radius:2px;background:var(--ac);transform-origin:bottom}
.sx-why:hover .ic-bars i{animation:ic-eq .9s ease-in-out infinite alternate}
.sx-why:hover .ic-bars i:nth-child(2){animation-delay:.15s}
.sx-why:hover .ic-bars i:nth-child(3){animation-delay:.3s}
.sx-why:hover .ic-bars i:nth-child(4){animation-delay:.45s}
@keyframes ic-eq{0%{transform:scaleY(.35)}100%{transform:scaleY(1.15)}}
.ic-toggle{position:relative;display:block;width:36px;height:20px;border-radius:99px;background:#3a3b39;transition:background .35s ease}
.ic-toggle i{position:absolute;top:3px;left:3px;width:14px;height:14px;border-radius:50%;background:#FEFCE1;transition:transform .35s cubic-bezier(.3,1.5,.5,1)}
.sx-why:hover .ic-toggle{background:var(--ac)}
.sx-why:hover .ic-toggle i{transform:translateX(16px)}
.ic-check-ring{transition:stroke-dashoffset .7s ease}
.ic-check-tick{transition:stroke-dashoffset .4s ease .45s}
.sx-why .ic-check-tick{stroke-dashoffset:0}
.sx-why:hover .ic-check-ring{stroke-dashoffset:0}
.sx-why:hover .ic-check-tick{animation:ic-tick .5s ease .5s both}
@keyframes ic-tick{from{stroke-dashoffset:16}to{stroke-dashoffset:0}}
.ic-orbit{position:relative;display:block;width:30px;height:30px}
.ic-orbit .c{position:absolute;left:50%;top:50%;width:9px;height:9px;margin:-4.5px 0 0 -4.5px;border-radius:50%;background:var(--ac)}
.ic-orbit .o{position:absolute;inset:0;border-radius:50%;border:1.4px dashed rgba(255,255,255,0.25)}
.ic-orbit .o b{position:absolute;top:-3.5px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:#FEFCE1}
.ic-orbit .o .b2{top:auto;bottom:-3px;background:#8A8A84;width:5px;height:5px}
.sx-why:hover .ic-orbit .o{animation:ic-spin 2.4s linear infinite}
@keyframes ic-spin{to{transform:rotate(360deg)}}
.ic-live{position:relative;display:block;width:30px;height:30px}
.ic-live .d{position:absolute;left:50%;top:50%;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;background:var(--ac)}
.ic-live .r{position:absolute;left:50%;top:50%;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;border:1.5px solid var(--ac);opacity:0}
.sx-why:hover .ic-live .r{animation:ic-ping 1.6s ease-out infinite}
.sx-why:hover .ic-live .r2{animation-delay:.8s}
@keyframes ic-ping{0%{transform:scale(1);opacity:.8}100%{transform:scale(3);opacity:0}}
.ic-lock-shackle{transition:transform .4s cubic-bezier(.3,1.5,.5,1);transform-origin:16px 11px}
.sx-why:hover .ic-lock-shackle{transform:translateY(-2.5px) rotate(18deg)}
@media (prefers-reduced-motion:reduce){.sx-why:hover .ic-bars i,.sx-why:hover .ic-orbit .o,.sx-why:hover .ic-live .r{animation:none}}
.sx-tab:hover .sx-si{color:var(--ac)}
.sx-si{display:block;overflow:visible;transition:color .3s ease}
.sx-si .p1,.sx-si .p2{transform-box:fill-box;transform-origin:center}
.sx-tab[aria-expanded="true"] .sx-si-design .p2{stroke-dasharray:22;animation:si-draw 2.4s ease-in-out infinite}
@keyframes si-draw{0%{stroke-dashoffset:22}55%,100%{stroke-dashoffset:0}}
.sx-tab[aria-expanded="true"] .sx-si-dev .p2{animation:si-blink 1.2s steps(1) infinite}
.sx-tab[aria-expanded="true"] .sx-si-dev .p1{animation:si-tap 1.2s ease-in-out infinite}
@keyframes si-blink{50%{opacity:.15}}
@keyframes si-tap{0%,100%{transform:scaleX(1)}50%{transform:scaleX(1.12)}}
.sx-tab[aria-expanded="true"] .sx-si-ai .p1{animation:si-twinkle 2.2s ease-in-out infinite}
.sx-tab[aria-expanded="true"] .sx-si-ai .p2{animation:si-twinkle 2.2s ease-in-out .5s infinite}
@keyframes si-twinkle{0%,100%{transform:scale(1) rotate(0)}50%{transform:scale(.72) rotate(45deg)}}
.sx-tab[aria-expanded="true"] .sx-si-woo{animation:si-bounce 1.4s cubic-bezier(.3,1.6,.5,1) infinite}
@keyframes si-bounce{0%,60%,100%{transform:translateY(0)}30%{transform:translateY(-3px)}}
.sx-tab[aria-expanded="true"] .sx-si-seo .p2{stroke-dasharray:12;animation:si-trend 2s ease-in-out infinite}
@keyframes si-trend{0%{stroke-dashoffset:12}50%,100%{stroke-dashoffset:0}}
.sx-tab[aria-expanded="true"] .sx-si-mgmt{animation:si-spin 6s linear infinite}
@keyframes si-spin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.sx-tab .sx-si,.sx-tab .sx-si .p1,.sx-tab .sx-si .p2{animation:none !important}}
.sx-bg{position:fixed;inset:0;z-index:-1;pointer-events:none;overflow:hidden}
.sx-bg-orb{position:absolute;border-radius:50%;will-change:transform}
.sx-bg-orb.o1{width:720px;height:720px;left:-120px;top:-160px;background:radial-gradient(closest-side,color-mix(in srgb,var(--ac) 34%,transparent),color-mix(in srgb,var(--ac) 10%,transparent) 55%,transparent)}
.sx-bg-orb.o2{width:820px;height:820px;right:-200px;bottom:-260px;background:radial-gradient(closest-side,rgba(254,252,225,0.11),rgba(254,252,225,0.03) 55%,transparent)}
.sx-bg-orb.o3{width:560px;height:560px;left:48%;top:34%;background:radial-gradient(closest-side,color-mix(in srgb,color-mix(in srgb,var(--ac) 60%,#E0362B) 30%,transparent),transparent 72%)}
.sx-bg-guides{position:absolute;top:0;bottom:0;left:50%;width:min(1348px,calc(100% - 48px));transform:translateX(-50%);border-left:1px solid rgba(255,255,255,0.06);border-right:1px solid rgba(255,255,255,0.06)}
.sx-bg-guides::before,.sx-bg-guides::after{content:"";position:absolute;top:0;bottom:0;width:1px;background:repeating-linear-gradient(to bottom,rgba(255,255,255,0.07) 0 2px,transparent 2px 8px)}
.sx-bg-guides::before{left:33.333%}
.sx-bg-guides::after{left:66.666%}
.sx-bg-grain{position:absolute;inset:-50%;width:200%;height:200%;opacity:.09;mix-blend-mode:overlay}
@media (prefers-reduced-motion:reduce){.sx-bg-orb{animation:none}}
.sx-glass{background:linear-gradient(140deg,rgba(255,255,255,0.075),rgba(255,255,255,0.018) 45%,rgba(255,255,255,0.035));-webkit-backdrop-filter:blur(16px) saturate(140%);backdrop-filter:blur(16px) saturate(140%);border:1px solid rgba(255,255,255,0.1);box-shadow:inset 0 1px 0 rgba(255,255,255,0.08),0 24px 60px rgba(0,0,0,0.28)}
.cw-page{position:absolute;inset:0;display:flex;flex-direction:column;gap:14px;padding:18px 20px;box-sizing:border-box;transition:transform .8s cubic-bezier(.2,.8,.2,1)}
.cw-list{position:relative;border-top:1px solid rgba(255,255,255,0.1)}
.cw-row{display:grid;grid-template-columns:70px minmax(0,1fr) 200px 90px 48px;align-items:center;gap:20px;padding:30px 4px;border-bottom:1px solid rgba(255,255,255,0.1);color:#FEFCE1;transition:padding .45s cubic-bezier(.2,.8,.2,1),color .3s ease}
.cw-row:hover{padding-left:20px}
.cw-row .t{font-size:clamp(26px,3.4vw,44px);line-height:1.05;font-weight:600;letter-spacing:-0.035em;transition:color .3s ease}
.cw-list:hover .cw-row .t{color:#6f6f6a}
.cw-list .cw-row:hover .t{color:#FEFCE1}
.cw-row .ar{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;border-radius:50%;border:1px solid rgba(255,255,255,0.14);color:#BBBAA6;transition:all .35s ease}
.cw-row:hover .ar{background:var(--ac);border-color:var(--ac);color:#0E0F0F;transform:rotate(45deg)}
.cw-prev{position:absolute;left:0;top:0;width:380px;height:240px;border-radius:18px;overflow:hidden;border:1px solid rgba(255,255,255,0.14);box-shadow:0 30px 70px rgba(0,0,0,0.55);pointer-events:none;z-index:5;opacity:0;transform:scale(.85);transition:opacity .3s ease,transform .4s cubic-bezier(.2,.8,.2,1)}
.cw-prev.on{opacity:1;transform:scale(1)}
@media (max-width:900px){.cw-row{grid-template-columns:44px minmax(0,1fr) 46px}.cw-row .c,.cw-row .y{display:none}.cw-prev{display:none}}
.sx-break{border-top:1px solid rgba(255,255,255,0.09)}
.sx-blink{animation:sx-blink 1.1s steps(1) infinite}
@keyframes sx-blink{50%{opacity:0}}
.sx-split>*{min-width:0;box-sizing:border-box}
.sx-split>:first-child{flex:1.35 1 520px}
.sx-split>:last-child{flex:1 1 320px}
.sx-split-svc>:first-child{flex:1 1 420px}
.sx-split-svc>:last-child{flex:1.15 1 440px}
.sx-split-faq>:first-child{flex:0.8 1 320px}
.sx-split-faq>:last-child{flex:1.2 1 440px}
@media (max-width:700px){.sx-marquee>div{width:300px !important}}
.sx-scene{position:absolute;top:0;right:0;width:58%;height:100%;perspective:1100px}
.sx-glow{position:absolute;left:50%;top:50%;width:520px;height:520px;margin:-260px 0 0 -260px;border-radius:50%;background:radial-gradient(closest-side,color-mix(in srgb,var(--ac) 14%,transparent),transparent);animation:sx-gl 16s ease-in-out infinite}
.sx-scale{position:absolute;left:50%;top:50%;width:0;height:0;transform-style:preserve-3d}
.sx-tilt{position:absolute;transform-style:preserve-3d;transform:rotateX(38deg) rotateY(-32deg);animation:sx-sway 14s ease-in-out infinite alternate}
.sx-spin{position:absolute;transform-style:preserve-3d;animation:sx-spin 12s linear infinite}
.sx-disc{position:absolute;left:-70px;top:-70px;width:140px;height:140px;border-radius:50%;background:radial-gradient(120% 90% at 25% 15%,color-mix(in srgb,var(--ac) 80%,#fff) 0%,var(--ac) 22%,color-mix(in srgb,var(--ac) 55%,#0b0605) 48%,color-mix(in srgb,var(--ac) 18%,#050303) 74%,#040303 100%);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--ac) 45%,transparent),inset 5px 3px 0 -3px rgba(255,255,255,0.16)}
@keyframes sx-spin{to{transform:rotateZ(360deg)}}
@keyframes sx-sway{from{transform:rotateX(34deg) rotateY(-40deg)}to{transform:rotateX(46deg) rotateY(-18deg)}}
@media (prefers-reduced-motion:reduce){.sx-spin,.sx-tilt{animation:none}}
.sx-cursor{position:absolute;z-index:5;left:72%;top:330px;pointer-events:none;animation:sx-cur 16s cubic-bezier(.45,.05,.3,1) infinite}
@keyframes sx-cur{
0%{left:72%;top:330px}
9%,13%{left:41.6%;top:36px}
17%,20%{left:46.6%;top:36px}
29%,34%{left:calc(100% - 96px);top:38px}
44%,49%{left:100px;top:392px}
56%,60%{left:236px;top:392px}
70%{left:70%;top:300px}
78%{left:76%;top:370px}
86%{left:66%;top:360px}
100%{left:72%;top:330px}}
.sx-ripple{position:absolute;left:-14px;top:-14px;width:30px;height:30px;border-radius:50%;border:2px solid var(--ac);opacity:0;animation:sx-rip 16s linear infinite}
@keyframes sx-rip{0%,30.5%{opacity:0;transform:scale(.3)}31%{opacity:1;transform:scale(.3)}33.5%{opacity:0;transform:scale(1.6)}34%,45.5%{opacity:0;transform:scale(.3)}46%{opacity:1;transform:scale(.3)}48.5%{opacity:0;transform:scale(1.6)}100%{opacity:0}}
.sx-h-work,.sx-h-studio{transition:none}
.sx-h-work{animation:sx-hw 16s linear infinite}
.sx-h-studio{animation:sx-hs 16s linear infinite}
@keyframes sx-hw{0%,8.5%{color:#A9A895}9%,13.5%{color:#FEFCE1}14%,100%{color:#A9A895}}
@keyframes sx-hs{0%,16.5%{color:#A9A895}17%,20.5%{color:#FEFCE1}21%,100%{color:#A9A895}}
.sx-h-start{animation:sx-hst 16s linear infinite}
@keyframes sx-hst{0%,28%{background:transparent;color:#FEFCE1}29%,34%{background:#FEFCE1;color:#0E0F0F}31%{transform:scale(.95)}32%{transform:scale(1)}35%,100%{background:transparent;color:#FEFCE1}}
.sx-h-explore{animation:sx-hex 16s linear infinite}
@keyframes sx-hex{0%,43%{box-shadow:none;transform:scale(1)}44%{box-shadow:0 0 0 6px rgba(254,252,225,0.14)}46%{transform:scale(.95)}47%{transform:scale(1)}49%{box-shadow:0 0 0 6px rgba(254,252,225,0.14)}50%,100%{box-shadow:none}}
.sx-h-reel{animation:sx-hr 16s linear infinite}
