/* ==========================================================================
   MOTION SYSTEM – one easing and timing for every transition
   ========================================================================== */
:root{--ease:cubic-bezier(.22,1,.36,1);--ease-io:cubic-bezier(.65,0,.35,1);--t-fast:.35s;--t:.5s;--t-slow:.8s}
a,button,label,summary{-webkit-tap-highlight-color:transparent;touch-action:manipulation}
/* inline transitions from the design get the same curve */
[style*="transition"]{transition-duration:var(--t) !important;transition-timing-function:var(--ease) !important}
.sx-btn{transition:background-color var(--t) var(--ease),color var(--t) var(--ease),border-color var(--t) var(--ease),box-shadow var(--t) var(--ease),transform var(--t) var(--ease);will-change:transform}
.sx-btn svg,.sx-link svg,.sx-ctile-ar svg{transition:transform var(--t) var(--ease)}
.sx-link{transition:color var(--t) var(--ease)}
.sx-link:hover,.sx-ccard:hover .sx-link,.sx-bcard:hover .sx-link{gap:8px}
.sx-link:hover svg,.sx-ccard:hover .sx-link svg,.sx-bcard:hover .sx-link svg{transform:translateX(4px)}
.sx-logo,.sx-nav-a,.sx-flink,.sx-btitle,.wa-t,.sx-toc-a,.sx-si,.sx-tab-title,.cw-row .t{transition:color var(--t) var(--ease),border-color var(--t) var(--ease)}
.sx-logo-img,.sx-wa,.sx-soc,.sx-upw,.sx-share,.sx-catnav a,.sx-ctile-ar,.cw-row .ar,.ab-role{transition:background-color var(--t) var(--ease),color var(--t) var(--ease),border-color var(--t) var(--ease),transform var(--t) var(--ease),box-shadow var(--t) var(--ease)}
.sx-why,.sx-ccard,.sx-rv,.sx-bcard,.sx-pn,.sx-ctile,.ab-val,.wa-shot,.sx-feat,.ws-next{transition:transform var(--t) var(--ease),border-color var(--t) var(--ease),background-color var(--t) var(--ease),box-shadow var(--t) var(--ease)}
.sx-bimg img,.wa-shot .nm-shot,.cw-page{transition:transform 1s var(--ease)}
.sx-hdr{transition:padding var(--t-slow) var(--ease)}
.sx-hdr-bar{transition:max-width var(--t-slow) var(--ease),padding var(--t-slow) var(--ease),background-color var(--t-slow) var(--ease),border-color var(--t-slow) var(--ease),box-shadow var(--t-slow) var(--ease)}
.sx-nav-ind{transition:transform var(--t) var(--ease),width var(--t) var(--ease),opacity var(--t-fast) var(--ease);left:0 !important}
.cw-prev{transition:opacity var(--t) var(--ease),transform var(--t) var(--ease)}
.wa-pill{transition:opacity var(--t) var(--ease),transform var(--t) var(--ease)}
.sx-in,.nm-srfm .srfm-input-common,.nm-srfm .ts-control,.nm-srfm .srfm-multi-choice-single .srfm-block-content-wrap,.nm-srfm .srfm-submit-button{transition:border-color var(--t) var(--ease),box-shadow var(--t) var(--ease),background-color var(--t) var(--ease),color var(--t) var(--ease),transform var(--t) var(--ease) !important}
/* work list: move content with transform instead of animating padding */
.cw-row,.cw-row:hover{padding-left:4px}
.cw-row>*{transition:transform .6s var(--ease),color var(--t) var(--ease),background-color var(--t) var(--ease),border-color var(--t) var(--ease)}
.cw-row:hover>*:not(.ar){transform:translateX(16px)}
/* FAQ / accordion bodies animate in JS; keep overflow tidy while they move */
.sx-faq+p,.nm-acc{overflow:hidden}
/* process line is driven frame by frame in JS */
.nm-pfill,.nm-vproc .sx-pline.nm-pfill{transition:none !important}
.sx-step>span{transition:color var(--t) var(--ease),background-color var(--t) var(--ease),border-color var(--t) var(--ease),box-shadow var(--t) var(--ease) !important}
/* touch screens: no sticky hover, a soft press instead */
@media (hover:none){
.sx-btn:hover,.sx-bcard:hover,.sx-rv:hover,.sx-pn:hover,.sx-ctile:hover,.sx-ccard:hover,.sx-why:hover,.ab-val:hover,.wa-card:hover .wa-shot,.sx-upw:hover,.sx-soc:hover,.sx-share:hover{transform:none}
.sx-bcard:hover .sx-bimg img,.wa-card:hover .nm-shot,.wa-card:hover .cw-page{transform:none}
.cw-row:hover>*:not(.ar){transform:none}
.sx-btn:active,.sx-share:active,.sx-soc:active,.sx-wa:active,.sx-burger:active{transform:scale(.96);transition-duration:.15s}
.sx-bcard:active,.sx-rv:active,.sx-pn:active,.sx-ctile:active,.sx-ccard:active,.wa-card:active .wa-shot{transform:scale(.985);transition-duration:.2s}
}
