/* No blue tap flash anywhere (accordion buttons reset styles with all:unset, so force it) */
html,body,*,*::before,*::after{-webkit-tap-highlight-color:transparent !important}
.sx-faq,.sx-tab,.sx-step,.sx-burger,.sx-share,.nm-srfm label{-webkit-user-select:none;user-select:none}
:focus:not(:focus-visible){outline:none}
.sx-faq:focus-visible,.sx-tab:focus-visible,.sx-step:focus-visible,.sx-btn:focus-visible,.sx-burger:focus-visible,a:focus-visible,button:focus-visible{outline:2px solid color-mix(in srgb,var(--ac) 80%,transparent);outline-offset:4px;border-radius:10px}
/* "What happens next" steps: scroll-driven line like the process timeline */
.sx-steps.nm-sjs::before{top:var(--nm-s0,8px);bottom:auto;height:var(--nm-slen,0);background:rgba(255,255,255,0.12)}
.nm-sfill{position:absolute;left:5px;top:var(--nm-s0,8px);width:3px;height:0;border-radius:3px;background:linear-gradient(180deg,color-mix(in srgb,var(--ac) 30%,transparent),var(--ac));box-shadow:0 0 14px color-mix(in srgb,var(--ac) 55%,transparent);pointer-events:none}
.sx-steps.nm-sjs .sx-step-i{opacity:.45;transition:opacity var(--t) var(--ease)}
.sx-steps.nm-sjs .sx-step-i::before{z-index:1;background:#0E0F0F;border:1px solid rgba(255,255,255,0.3);box-sizing:border-box;box-shadow:none;transition:background-color var(--t) var(--ease),border-color var(--t) var(--ease),box-shadow var(--t) var(--ease)}
.sx-steps.nm-sjs .sx-step-i.is-done,.sx-steps.nm-sjs .sx-step-i.is-on{opacity:1}
.sx-steps.nm-sjs .sx-step-i.is-done::before{background:var(--ac);border-color:var(--ac)}
.sx-steps.nm-sjs .sx-step-i.is-on::before{background:var(--ac);border-color:var(--ac);box-shadow:0 0 0 6px color-mix(in srgb,var(--ac) 22%,transparent),0 0 18px color-mix(in srgb,var(--ac) 55%,transparent)}
/* Ember ring logo: slow continuous spin, like the hero disc */
.sx-brand img,footer a[href="/"] img{transform-origin:50% 50%;animation:nm-spin 14s linear infinite;will-change:transform;backface-visibility:hidden}
@keyframes nm-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.sx-brand img,footer a[href="/"] img{animation:none}}
/* Footer social icons: fully round (colours unchanged) */
.sx-soc{border-radius:50%}
/* Icon boxes everywhere: circles (colours and borders unchanged) */
.sx-why-ic,.sx-cic,.ab-val-ic{border-radius:50% !important}
/* Hero top spacing: one value for every page (via .sx-sec-hero) */
.sx-sec-hero{padding-top:28px !important}
@media (min-width:641px){.sx-sec-hero{padding-top:40px !important}}
@media (min-width:901px){.sx-sec-hero{padding-top:56px !important}}
.sx-mmenu{position:absolute;left:24px;right:24px;top:100%;z-index:60;margin-top:10px;max-height:calc(100dvh - 110px);will-change:transform,opacity,clip-path}
.sx-hdr.is-scrolled .sx-mmenu{margin-top:8px}
/* ===== Mobile menu: Tiles (floats over the page, page behind blurred, animated background, big tile icons) ===== */
.sx-hdr.menu-open::before{content:"";position:fixed;inset:0;z-index:-1;background:rgba(8,9,9,0.5);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.sx-mmenu{grid-template-columns:1fr 1fr;gap:10px;padding:12px;border-radius:26px;border:1px solid rgba(255,255,255,0.1);
  background:#0E0F0F;overflow:hidden;isolation:isolate;
  box-shadow:0 30px 70px rgba(0,0,0,0.6);-webkit-backdrop-filter:none;backdrop-filter:none}
.sx-mmenu .sx-mlink{position:relative;display:flex;flex-direction:column;justify-content:space-between;align-items:flex-start;gap:14px;min-height:84px;padding:14px 16px;border-radius:16px;font-size:17px;border:1px solid rgba(255,255,255,0.08);background:rgba(255,255,255,0.03);transition:border-color var(--t) var(--ease),background-color var(--t) var(--ease),color var(--t) var(--ease)}
.sx-mmenu .sx-mlink:active,.sx-mmenu .sx-mlink:hover{border-color:color-mix(in srgb,var(--ac) 45%,transparent);background:rgba(255,255,255,0.05);color:#FEFCE1}
.sx-mmenu .sx-mlink[aria-current="page"]{border-color:color-mix(in srgb,var(--ac) 35%,transparent)}
.sx-mmenu .sx-btn{margin-top:4px !important;min-height:50px;justify-content:center;font-size:15px;padding:0 14px}
.sx-mmenu .sx-btn svg{width:17px;height:17px}

/* icons: 30% opacity, slow subtle loops */
.nm-mi{display:block;width:24px;height:24px;color:#FEFCE1;opacity:.3;transition:opacity var(--t) var(--ease),color var(--t) var(--ease);overflow:visible}
.sx-mlink:hover .nm-mi,.sx-mlink:active .nm-mi,.sx-mlink[aria-current="page"] .nm-mi{opacity:1;color:var(--ac)}
.nm-mi *{transform-box:fill-box;transform-origin:center}
/* Services – layers: top layer floats */
.nm-mi-services .l1{animation:mi-float 3.2s ease-in-out infinite}
/* Work – browser: content line draws */
.nm-mi-work .ln{stroke-dasharray:12;animation:mi-draw 3s ease-in-out infinite}
/* Process – route: dot travels */
.nm-mi-process .dot{animation:mi-route 3.6s ease-in-out infinite}
/* Reviews – star: gentle pulse */
.nm-mi-reviews .st{animation:mi-pulse 2.8s ease-in-out infinite}
/* Articles – page: lines write in turn */
.nm-mi-articles .a1{stroke-dasharray:10;animation:mi-draw 3.2s ease-in-out infinite}
.nm-mi-articles .a2{stroke-dasharray:10;animation:mi-draw 3.2s ease-in-out .4s infinite}
.nm-mi-articles .a3{stroke-dasharray:10;animation:mi-draw 3.2s ease-in-out .8s infinite}
/* About – person: head nods */
.nm-mi-about .hd{animation:mi-nod 3.4s ease-in-out infinite}
@keyframes mi-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}
@keyframes mi-draw{0%{stroke-dashoffset:12}45%,70%{stroke-dashoffset:0}100%{stroke-dashoffset:-12}}
@keyframes mi-route{0%,8%{transform:translateX(0)}46%,54%{transform:translateX(15px)}92%,100%{transform:translateX(0)}}
@keyframes mi-pulse{0%,100%{transform:scale(1) rotate(0)}50%{transform:scale(1.12) rotate(8deg)}}
@keyframes mi-nod{0%,100%{transform:translateY(0)}40%{transform:translateY(1.2px)}60%{transform:translateY(-.6px)}}
@media (prefers-reduced-motion:reduce){.nm-mi *{animation:none !important}}

/* menu background: the page background, animated (drifting ember + cream glows, grain) */
.nm-mbg{position:absolute;inset:0;z-index:-1;pointer-events:none;overflow:hidden;border-radius:inherit}
.nm-mbg i{position:absolute;border-radius:50%;will-change:transform}
.nm-mbg .b1{width:320px;height:320px;left:-90px;top:-110px;background:radial-gradient(closest-side,color-mix(in srgb,var(--ac) 38%,transparent),color-mix(in srgb,var(--ac) 10%,transparent) 55%,transparent);animation:nm-drift1 14s ease-in-out infinite alternate}
.nm-mbg .b2{width:360px;height:360px;right:-140px;bottom:-150px;background:radial-gradient(closest-side,rgba(254,252,225,0.12),rgba(254,252,225,0.03) 55%,transparent);animation:nm-drift2 18s ease-in-out infinite alternate}
.nm-mbg .b3{width:220px;height:220px;left:45%;top:40%;background:radial-gradient(closest-side,color-mix(in srgb,color-mix(in srgb,var(--ac) 60%,#E0362B) 30%,transparent),transparent 72%);animation:nm-drift3 11s ease-in-out infinite alternate}
.nm-mbg::after{content:"";position:absolute;inset:0;background:url(/wp-content/uploads/2026/11/nm-grain.png) repeat;background-size:128px 128px;opacity:.06}
@keyframes nm-drift1{0%{transform:translate(0,0) scale(1)}50%{transform:translate(120px,140px) scale(1.15)}100%{transform:translate(40px,260px) scale(.95)}}
@keyframes nm-drift2{0%{transform:translate(0,0) scale(1)}50%{transform:translate(-140px,-120px) scale(1.2)}100%{transform:translate(-60px,-240px) scale(1)}}
@keyframes nm-drift3{0%{transform:translate(0,0) scale(1)}50%{transform:translate(-90px,60px) scale(1.25)}100%{transform:translate(40px,-80px) scale(.9)}}
@media (prefers-reduced-motion:reduce){.nm-mbg i{animation:none}}
/* big icons: absolute, right side, slightly cut off by the tile edge */
.sx-mmenu .sx-mlink{overflow:hidden;justify-content:flex-end;isolation:isolate}
.sx-mmenu .sx-mlink>span{position:relative;z-index:1}
.sx-mmenu .nm-mi{position:absolute;right:-16px;top:50%;width:72px;height:72px;margin-top:-36px;z-index:0;stroke-width:1.15}
/* Upwork avatar: outline circle with a small ember "up" mark (testimonials + contact) */
svg:has(> g[transform^="translate(15.5 16.5)"])>circle:first-of-type{fill:rgba(255,255,255,0.05)}
svg:has(> g[transform^="translate(15.5 16.5)"])>circle:nth-of-type(2){stroke:rgba(255,255,255,0.14);stroke-width:1.5}
svg:has(> g[transform^="translate(15.5 16.5)"])>g{transform:translate(20.6px,21.2px) scale(.95)}
svg:has(> g[transform^="translate(15.5 16.5)"])>g path{fill:var(--ac)}
/* Contact cards: outline icons like the rest of the site */
