.sx-ccard .sx-cic,.sx-cic[style*="width: 42px"]{transition:border-color var(--t) var(--ease),background-color var(--t) var(--ease),transform var(--t) var(--ease)}
.sx-ccard:hover .sx-cic{border-color:color-mix(in srgb,var(--ac) 45%,transparent);transform:translateY(-2px)}
/* All glass cards use the testimonial-card finish: glass gradient + thin border + top highlight, no drop shadow */
.sx-glass{box-shadow:inset 0 1px 0 rgba(255,255,255,0.08)}
/* "Why clients choose me" cards: same finish as the homepage review cards
   (gradient + thin border + top highlight, 28px padding, 20px radius, no glass blur/colour boost) */
.sx-why.sx-glass{padding:28px;border-radius:20px;background:linear-gradient(140deg,rgba(255,255,255,0.075),rgba(255,255,255,0.018) 45%,rgba(255,255,255,0.035));border:1px solid rgba(255,255,255,0.1);box-shadow:inset 0 1px 0 rgba(255,255,255,0.08);-webkit-backdrop-filter:none;backdrop-filter:none}
.sx-why.sx-glass:hover{background:linear-gradient(140deg,rgba(255,255,255,0.075),rgba(255,255,255,0.018) 45%,rgba(255,255,255,0.035));border-color:color-mix(in srgb,var(--ac) 40%,transparent)}
/* All glass cards: the homepage review-card finish (gradient + thin border + top highlight, no blur/colour boost) */
.sx-glass{background:linear-gradient(140deg,rgba(255,255,255,0.075),rgba(255,255,255,0.018) 45%,rgba(255,255,255,0.035));border:1px solid rgba(255,255,255,0.1);box-shadow:inset 0 1px 0 rgba(255,255,255,0.08);-webkit-backdrop-filter:none;backdrop-filter:none}
.dv-stage.sx-glass{background:radial-gradient(60% 70% at 45% 35%,color-mix(in srgb,var(--ac) 12%,transparent),transparent 70%),linear-gradient(140deg,rgba(255,255,255,0.075),rgba(255,255,255,0.018) 45%,rgba(255,255,255,0.035))}
/* Card slider (all sizes): homepage latest articles – 3 visible on desktop, 2 tablet, 1 phone */
.nm-cslide{display:flex !important;gap:24px !important;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;scroll-behavior:smooth;padding:4px 0 10px}
