.sx-logo>svg,.sx-logo>span[aria-hidden],.sx-logo .sx-logo-img{transition:filter 1.1s var(--ease),opacity 1.1s var(--ease),color 1.1s var(--ease)}
.sx-logo:hover,.sx-logo.is-glow{color:var(--ac);text-shadow:0 0 18px color-mix(in srgb,var(--ac) 35%,transparent)}
.sx-logo:hover>svg,.sx-logo.is-glow>svg,.sx-logo:hover>span[aria-hidden],.sx-logo.is-glow>span[aria-hidden]{filter:drop-shadow(0 0 8px color-mix(in srgb,var(--ac) 55%,transparent))}
