/* Burger → ✕ morph (smooth), ember when open */
.sx-burger{transition:color .5s var(--ease),border-color .5s var(--ease),background-color .5s var(--ease),transform .15s var(--ease)}
.nm-bars{position:relative;display:block;width:18px;height:12px}
