/* ===== Services mega menu (desktop) ===== */
.sx-nav-a.nm-has-mega{display:inline-flex;align-items:center;gap:6px}
.sx-nav-a.nm-has-mega::after{content:"";width:8px;height:8px;margin-top:-3px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg);opacity:.6;transition:transform .45s var(--ease),margin .45s var(--ease)}
