.nm-mega{position:absolute;left:50%;top:100%;z-index:70;width:min(920px,calc(100vw - 48px));margin-top:12px;transform:translateX(-50%);display:grid;grid-template-columns:340px 1fr;gap:10px;padding:10px;border-radius:26px;border:1px solid rgba(255,255,255,0.1);background:#121313;box-shadow:0 40px 90px rgba(0,0,0,0.6);opacity:0;visibility:hidden;clip-path:inset(0 0 100% 0 round 26px);transition:opacity .45s var(--ease),clip-path .6s var(--ease),visibility 0s .6s}
