.nm-mega-item::before{content:"";position:absolute;left:0;top:18px;bottom:18px;width:2px;border-radius:2px;background:var(--ac);transform:scaleY(0);transition:transform .45s var(--ease)}
.nm-mega-item.is-on::before{transform:scaleY(1)}
.nm-mega-all{margin-top:auto;padding:14px 16px 6px;font-size:14px;color:#A9A895;display:inline-flex;gap:8px;align-items:center}
.nm-mega-all:hover{color:var(--ac)}
.nm-mega-view{position:relative;min-height:400px;border-radius:18px;overflow:hidden;border:1px solid rgba(255,255,255,0.08);background:#0E0F0F}
