.nm-msub a.row .ic{flex:none;display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.04)}
.nm-msub a.row .ic img,.nm-msub a.row .ic svg{width:22px;height:22px}
.nm-msub a.row b{display:block;font-size:16px;font-weight:500}
.nm-msub a.row span.d{display:block;margin-top:3px;font-size:13px;line-height:1.4;color:#8A8A84}
.nm-msub a.row::after{content:"";margin-left:auto;flex:none;width:8px;height:8px;border-right:1.5px solid #8A8A84;border-top:1.5px solid #8A8A84;transform:rotate(45deg)}
.nm-msub .nm-msub-cta{margin-top:4px;justify-content:center;min-height:50px}
.sx-mmenu .sx-mlink[data-sub] .nm-mi-more{position:absolute;top:14px;left:14px;width:22px;height:22px;border-radius:50%;border:1px solid rgba(255,255,255,0.14);display:inline-flex;align-items:center;justify-content:center;z-index:1}
.sx-mmenu .sx-mlink[data-sub] .nm-mi-more::before{content:"";width:6px;height:6px;border-right:1.5px solid #BBBAA6;border-top:1.5px solid #BBBAA6;transform:rotate(45deg);margin-left:-2px}

/* list icons */
.nm-mega-item .ic{flex:none;display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);color:#BBBAA6;transition:color .4s var(--ease),border-color .4s var(--ease),background-color .4s var(--ease)}
.nm-mega-item .ic svg{width:19px;height:19px}
.nm-mega-item.is-on .ic{color:var(--ac);border-color:color-mix(in srgb,var(--ac) 45%,transparent);background:color-mix(in srgb,var(--ac) 8%,transparent)}
.nm-mega-item .tx{display:block;margin:0}
.nm-mega-item .tx>span{display:block;margin-top:3px;font-size:13px;line-height:1.4;color:#8A8A84}
.nm-mega-item b{font-size:15.5px}
/* card background from each service glow */
.nm-mega-card .bg{background:radial-gradient(70% 80% at 85% 10%,var(--g),transparent 60%),radial-gradient(60% 70% at 10% 100%,color-mix(in srgb,var(--ac) 26%,transparent),transparent 60%),#121212}
/* builder chips on Web Development */
.nm-mega-b{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}
.nm-mega-b a{display:inline-flex;align-items:center;gap:9px;min-height:44px;padding:0 14px 0 8px;border-radius:999px;border:1px solid rgba(255,255,255,0.12);background:rgba(14,15,15,0.45);font-size:14px;color:#E4E2CB;transition:border-color .4s var(--ease),color .4s var(--ease),background-color .4s var(--ease)}
.nm-mega-b a img{width:28px;height:28px;border-radius:50%;background:rgba(255,255,255,0.06);padding:5px;box-sizing:border-box}
.nm-mega-b a svg{width:13px;height:13px;opacity:.5;transition:transform .4s var(--ease),opacity .4s var(--ease)}
.nm-mega-b a:hover{border-color:color-mix(in srgb,var(--ac) 55%,transparent);color:#FEFCE1}
.nm-mega-b a:hover svg{transform:translateX(3px);opacity:1;color:var(--ac)}
/* mobile fixes: tiles fully hide behind sub-view; grid rows don't stretch */
.sx-mmenu{align-content:start}
.sx-mmenu.sub-open>:not(.nm-msub):not(.nm-mbg){transform:translateX(-18%) !important;opacity:0 !important;pointer-events:none}
.nm-msub a.row .ic{color:var(--ac)}
.nm-msub a.row .ic svg{width:20px;height:20px}
.sx-mmenu.sub-open{max-height:calc(100dvh - 96px);overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none}
.nm-mega-item{padding:10px 14px}

/* ===== Services archive cards ===== */
.nm-svc-card{display:flex;flex-direction:column;color:inherit;text-decoration:none;transition:border-color .5s var(--ease),transform .6s var(--ease)}
.nm-svc-card:hover{border-color:color-mix(in srgb,var(--ac) 45%,transparent);transform:translateY(-4px)}
.nm-svc-ic{display:inline-flex;align-items:center;justify-content:center;width:52px;height:52px;border-radius:50%;border:1px solid rgba(255,255,255,0.14);background:rgba(255,255,255,0.03);transition:border-color .5s var(--ease),background-color .5s var(--ease)}
.nm-svc-ic::before{content:"";width:22px;height:22px;background-color:var(--ac);-webkit-mask:center/contain no-repeat;mask:center/contain no-repeat}
.nm-svc-card[data-ic="bricks"] .nm-svc-ic::before,.nm-svc-card[data-ic="oxygen"] .nm-svc-ic::before,.nm-svc-card[data-ic="etch"] .nm-svc-ic::before{-webkit-mask:none;mask:none}
.nm-svc-card:hover .nm-svc-ic{border-color:color-mix(in srgb,var(--ac) 50%,transparent);background:color-mix(in srgb,var(--ac) 8%,transparent)}
.nm-svc-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:auto;padding-top:28px}
.nm-svc-time{padding:5px 11px;border-radius:999px;border:1px solid rgba(255,255,255,0.12);font-size:12.5px;color:#E4E2CB}
.nm-svc-go{display:inline-flex;align-items:center;gap:8px;font-size:14px;color:#BBBAA6;transition:color .4s var(--ease)}
.nm-svc-go svg{transition:transform .5s var(--ease)}
.nm-svc-card:hover .nm-svc-go{color:var(--ac)}
.nm-svc-card:hover .nm-svc-go svg{transform:translateX(4px)}
@media (max-width:700px){.nm-svc-grid{grid-template-columns:1fr !important}}
