/* homepage services: View service link per panel */
.nm-panel-go{align-self:flex-start;margin-top:22px;min-height:38px !important;padding:0 16px !important;font-size:14px !important;gap:8px}
.nm-panel-go svg{width:14px;height:14px;transition:transform .5s var(--ease)}
.nm-panel-go:hover svg{transform:translateX(4px)}

/* ===== Animated service icons: draw-in + micro-interactions ===== */
.nm-ai{overflow:visible}
.nm-ai path{stroke-dasharray:1;stroke-dashoffset:1;transform-box:fill-box;transform-origin:center;transition:stroke-dashoffset 1.1s var(--ease) calc(var(--i,0) * 90ms + 200ms)}
.nm-ai .p2{transition-delay:calc(var(--i,0) * 90ms + 520ms)}
.sx-hdr.mega-open .nm-mega .nm-ai path,.sx-mmenu.sub-open .nm-msub .nm-ai path,.nm-svc-card.is-drawn .nm-ai path,.nm-mega-card .nm-ai path{stroke-dashoffset:0}
.nm-svc-ic.has-svg::before{display:none}
.nm-svc-ic.has-svg{color:var(--ac)}
.nm-svc-ic.has-svg svg{width:22px;height:22px}
.nm-msub a.row .ic{transition:border-color .5s var(--ease),background-color .5s var(--ease),transform .5s var(--ease)}
.nm-msub a.row:active .ic,.nm-msub a.row.is-tap .ic{border-color:color-mix(in srgb,var(--ac) 50%,transparent);background:color-mix(in srgb,var(--ac) 10%,transparent);transform:scale(.94)}
/* keyframes */
@keyframes nmRedraw{0%{stroke-dashoffset:1}100%{stroke-dashoffset:0}}
@keyframes nmSpread{0%,100%{transform:scaleX(1)}45%{transform:scaleX(1.16)}}
@keyframes nmTilt{0%,100%{transform:rotate(0)}40%{transform:rotate(-16deg)}70%{transform:rotate(6deg)}}
@keyframes nmTwinkle{0%,100%{transform:scale(1) rotate(0)}40%{transform:scale(.82) rotate(45deg)}70%{transform:scale(1.08) rotate(80deg)}}
@keyframes nmPop{0%,100%{transform:scale(1)}50%{transform:scale(1.6)}}
@keyframes nmLift{0%,100%{transform:translateY(0)}35%{transform:translateY(-2.5px)}65%{transform:translateY(.5px)}}
@keyframes nmSpin{0%{transform:rotate(0)}100%{transform:rotate(120deg)}}
@keyframes nmLogo{0%,100%{transform:scale(1) rotate(0)}45%{transform:scale(1.14) rotate(-8deg)}}
/* triggers: hover (desktop), active list item, tap (touch), and once when the mobile list opens */
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-design .p2,.sx-mmenu.sub-open .nm-ai-design .p2{animation:nmRedraw .9s var(--ease) both}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-dev .p1,.sx-mmenu.sub-open .nm-ai-dev .p1{animation:nmSpread .8s var(--ease)}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-dev .p2,.sx-mmenu.sub-open .nm-ai-dev .p2{animation:nmTilt .8s var(--ease)}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-ai .p1,.sx-mmenu.sub-open .nm-ai-ai .p1{animation:nmTwinkle .9s var(--ease)}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-ai .p2,.sx-mmenu.sub-open .nm-ai-ai .p2{animation:nmPop .7s var(--ease) .15s}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-woo,.sx-mmenu.sub-open .nm-ai-woo{animation:nmLift .8s var(--ease)}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-woo .p2,.sx-mmenu.sub-open .nm-ai-woo .p2{animation:nmLift .8s var(--ease) .1s}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-seo .p1,.sx-mmenu.sub-open .nm-ai-seo .p1{animation:nmTilt .9s var(--ease)}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-seo .p2,.sx-mmenu.sub-open .nm-ai-seo .p2{animation:nmRedraw .8s var(--ease) .1s both}
:is(.nm-mega-item.is-on,.nm-svc-card:hover,.nm-svc-card.is-tap,.nm-msub a.row:hover,.nm-msub a.row.is-tap) .nm-ai-mgmt .p1,.sx-mmenu.sub-open .nm-ai-mgmt .p1{animation:nmSpin 1s var(--ease)}
/* stagger the one-time play when the mobile list opens, after the draw-in */
.sx-mmenu.sub-open .nm-msub .nm-ai,.sx-mmenu.sub-open .nm-msub .nm-ai path{animation-delay:calc(var(--i,0) * 110ms + 1.1s) !important}
/* builder logo cards */
.nm-svc-card:is(:hover,.is-tap)[data-ic="bricks"] .nm-svc-ic::before,.nm-svc-card:is(:hover,.is-tap)[data-ic="oxygen"] .nm-svc-ic::before,.nm-svc-card:is(:hover,.is-tap)[data-ic="etch"] .nm-svc-ic::before{animation:nmLogo .8s var(--ease)}
.nm-svc-card .nm-svc-ic{transition:border-color .5s var(--ease),background-color .5s var(--ease),transform .6s var(--ease)}
.nm-svc-card:hover .nm-svc-ic{transform:scale(1.06)}
@media (prefers-reduced-motion:reduce){.nm-ai path{stroke-dashoffset:0 !important;transition:none}.nm-ai,.nm-ai path,.nm-svc-ic::before{animation:none !important}}

/* ===== One text-link style site-wide ===== */
a.sx-link{display:inline-flex;align-items:center;gap:8px;font-size:15px;font-weight:400;line-height:1.4;color:#FEFCE1;padding-bottom:4px;border-bottom:1px solid color-mix(in srgb,var(--ac) 60%,transparent);transition:color var(--t) var(--ease),border-color var(--t) var(--ease)}
a.sx-link:hover{gap:8px;color:var(--ac);border-bottom-color:var(--ac)}
a.sx-link svg{flex:none;width:15px;height:15px;transition:transform var(--t) var(--ease)}
a.sx-link:hover svg{transform:translateX(4px)}
a.sx-link.is-inline{display:inline;padding-bottom:1px;font-size:inherit}

/* ===== One corner scale: small cards 20px, large panels 24px ===== */
.ab-stat.sx-glass,.ab-val.sx-glass,.sx-ccard.sx-glass{border-radius:20px !important}
.sx-glass[style*="border-radius: 22px"],.sx-glass[style*="border-radius: 26px"],.sx-glass[style*="border-radius: 28px"],.sx-glass[style*="border-radius: 30px"],.frame.sx-glass,.dv-stage.sx-glass,.ws-meta.sx-glass{border-radius:24px !important}
/* search button text matches the other buttons */
form .sx-btn[type="submit"]{font-size:15px !important}

/* mobile services view: "All services" link + footer "All services" */
.nm-msub-top a.nm-msub-all{font-size:14px;padding-bottom:3px}
.nm-msub-top a.nm-msub-all svg{width:14px;height:14px}
.sx-flink.nm-flink-all{color:#FEFCE1;border-bottom:1px solid color-mix(in srgb,var(--ac) 60%,transparent);padding-bottom:3px;align-self:flex-start}
.sx-flink.nm-flink-all:hover{color:var(--ac);border-bottom-color:var(--ac)}

