// SEO link attributes on the final HTML of every front-end page:
// - external links: rel="nofollow noopener noreferrer"
// - internal links: followed (any nofollow removed) and a title with the destination page name
add_action('template_redirect', function () {
    if (is_admin() || is_feed() || wp_doing_ajax() || (defined('REST_REQUEST') && REST_REQUEST) || isset($_GET['etch'])) return;
    ob_start('nm_seo_links');
}, 1);

if (!function_exists('nm_seo_links')) {
function nm_seo_link_title($href) {
    static $cache = [];
    if (isset($cache[$href])) return $cache[$href];
    $home = home_url('/');
    $u = wp_parse_url($href);
    $path = isset($u['path']) ? trailingslashit($u['path']) : '/';
    $frag = $u['fragment'] ?? '';
    $title = '';
    if ($path === '/' && $frag) {
        $title = ucwords(str_replace(['-', '_'], ' ', $frag));
    } elseif ($path === '/') {
        $title = 'Home';
    } elseif (($pid = url_to_postid(home_url($path))) > 0) {
        $title = get_the_title($pid);
    } elseif ($path === '/work/') {
        $title = 'Work';
    } elseif (preg_match('#^/category/([^/]+)/$#', $path, $m) && ($t = get_term_by('slug', $m[1], 'category'))) {
        $title = $t->name . ' articles';
    }
    $title = trim(wp_strip_all_tags(html_entity_decode((string) $title, ENT_QUOTES, 'UTF-8')));
    return $cache[$href] = $title;
}

function nm_seo_links($html) {
    if (stripos($html, '<a ') === false) return $html;
    $host = wp_parse_url(home_url('/'), PHP_URL_HOST);
    $bare = preg_replace('/^www\./', '', $host);
    return preg_replace_callback('#<a\s[^>]*>#i', function ($m) use ($host, $bare) {
        $tag = $m[0];
        if (!preg_match('#\shref\s*=\s*(["\'])(.*?)\1#i', $tag, $h)) return $tag;
        $href = html_entity_decode($h[2], ENT_QUOTES, 'UTF-8');
        if ($href === '' || $href[0] === '#' || preg_match('#^(mailto:|tel:|javascript:|sms:)#i', $href)) return $tag;
        $lh = wp_parse_url($href, PHP_URL_HOST);
        $internal = !$lh || preg_replace('/^www\./', '', strtolower($lh)) === $bare;
        $rel = preg_match('#\srel\s*=\s*(["\'])(.*?)\1#i', $tag, $r) ? preg_split('/\s+/', strtolower(trim($r[2]))) : [];
        if ($internal) {
            $rel = array_values(array_diff($rel, ['nofollow', 'ugc', 'sponsored']));
            if (!preg_match('#\stitle\s*=#i', $tag)) {
                $abs = $lh ? $href : home_url($href);
                $t = nm_seo_link_title($abs);
                if ($t !== '') $tag = preg_replace('#^<a\s#i', '<a title="' . esc_attr($t) . '" ', $tag);
            }
        } else {
            $rel = array_values(array_unique(array_merge(array_diff($rel, ['']), ['nofollow', 'noopener', 'noreferrer'])));
        }
        $tag = preg_replace('#\srel\s*=\s*(["\']).*?\1#i', '', $tag);
        if ($rel) $tag = preg_replace('#^<a\s#i', '<a rel="' . esc_attr(implode(' ', $rel)) . '" ', $tag);
        return $tag;
    }, $html);
}
}

