// [nm_prev_next] – previous / next cards for articles and projects.
add_shortcode('nm_prev_next', function () {
    if (!is_singular()) return '';
    $type = get_post_type();
    $label = $type === 'work' ? 'project' : 'article';
    $card = function ($p, $dir) use ($label) {
        if (!$p) return '<span></span>';
        $img = get_the_post_thumbnail_url($p, 'medium');
        if (!$img && function_exists('get_field')) { $d = get_field('desktop_screenshot', $p->ID); if (is_array($d)) $img = $d['sizes']['medium'] ?? $d['url']; elseif (is_numeric($d)) $img = wp_get_attachment_image_url((int) $d, 'medium'); }
        $next = $dir === 'next';
        $html = '<a href="' . esc_url(get_permalink($p)) . '" class="sx-pn sx-glass"' . ($next ? ' style="flex-direction: row-reverse; text-align: right;"' : '') . '>';
        if ($img) $html .= '<img src="' . esc_url($img) . '" alt="" loading="lazy">';
        $html .= '<span style="min-width: 0"><span class="sx-mono" style="display: block">' . ($next ? 'Next ' . $label . ' →' : '← Previous ' . $label) . '</span>';
        $html .= '<span class="sx-btitle" style="display: block; margin-top: 8px; font-size: 16.5px; line-height: 1.35; font-weight: 600">' . esc_html(get_the_title($p)) . '</span></span></a>';
        return $html;
    };
    $prev = get_previous_post();
    $next = get_next_post();
    if (!$prev && !$next) return '';
    return '<div class="nm-pn" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 16px; margin-top: 64px">' . $card($prev, 'prev') . $card($next, 'next') . '</div>';
});
